const $ = (id) => document.getElementById(id);
const state = { picked: new Set(), removed: new Map(), region: "", kind: "", q: "" };

const posName = Object.fromEntries(DATA.positions.map(p => [p.id, p.name]));

/* Поставщик считается подтверждённым, когда сошлись три вещи: контакт прошёл
   проверку, компания найдена по ИНН и она закрывает хотя бы одну позицию. */
const isVerified = (s) => s.conf === "high" && !!s.inn && s.covers.length > 0;

function cleanTitle(s) {
  let t = (s.title || s.host).split(/[|—–]/)[0].replace(/\.\.\.$/, "").trim();
  if (t.length > 62) t = t.slice(0, 62).replace(/\s+\S*$/, "") + "…";
  return t || s.host;
}

function renderPositions() {
  $("positions").innerHTML = DATA.positions.map(p =>
    `<div class="pos"><b>${p.name}</b><span>${p.qty}</span></div>`).join("");
}

function renderFilters() {
  const regions = [...new Set(DATA.suppliers.map(s => s.region).filter(Boolean))].sort();
  $("fRegion").insertAdjacentHTML("beforeend",
    regions.map(r => `<option value="${r}">${r}</option>`).join(""));
}

function visible() {
  return DATA.suppliers.filter(s => {
    if (state.removed.has(s.host)) return false;
    if (state.region && s.region !== state.region) return false;
    if (state.kind && s.kind !== state.kind) return false;
    if (state.q) {
      const hay = (s.host + " " + s.title).toLowerCase();
      if (!hay.includes(state.q.toLowerCase())) return false;
    }
    return true;
  });
}

function cardHtml(s) {
  const verified = isVerified(s);
  const covered = DATA.positions.map(p => s.covers.includes(p.id));
  const best = s.emails[0];
  const rest = Math.max(0, s.n_emails - 1);

  const tags = [];
  if (s.region) tags.push(`<span class="tag">${s.region}</span>`);
  if (s.kind)   tags.push(`<span class="tag">${s.kind}</span>`);
  if (s.inn)    tags.push(`<span class="tag mono">ИНН ${s.inn}</span>`);
  if (!s.inn)   tags.push(`<span class="tag warn">реквизиты не найдены</span>`);
  if (s.web)    tags.push(`<span class="tag warn">сайт недоступен</span>`);

  return `
  <article class="card ${verified ? "verified" : "maybe"} ${state.picked.has(s.host) ? "picked" : ""}" data-host="${s.host}">
    <div class="pick">
      <input type="checkbox" ${state.picked.has(s.host) ? "checked" : ""}
             aria-label="Выбрать ${s.host}" data-act="pick">
    </div>
    <div class="body">
      <h3>${cleanTitle(s)}</h3>
      <a class="dom" href="https://${s.host}" target="_blank" rel="noopener">${s.host}</a>
      <div class="meta">${tags.join("")}</div>
      <div class="reason">
        <span class="lbl">Почему в списке</span>
        ${s.snippet ? s.snippet.slice(0, 190) + (s.snippet.length > 190 ? "…" : "")
                    : "Компания найдена в поисковой выдаче по позициям заявки."}
      </div>
      <div class="acts">
        <button class="btn" data-act="open">Открыть сайт</button>
        <button class="btn stop" data-act="black">В чёрный список</button>
        <button class="btn stop" data-act="irrelevant">Нерелевантно</button>
      </div>
    </div>
    <div class="side">
      <div>
        <div class="cov-head">
          <span class="lbl">Закрывает позиций</span>
          <span class="n">${s.covers.length} / ${DATA.positions.length}</span>
        </div>
        <div class="cov-bars">${covered.map(c => `<i class="${c ? "on" : ""}"></i>`).join("")}</div>
      </div>
      <div class="cov-list">
        ${DATA.positions.map(p => {
          const on = s.covers.includes(p.id);
          const short = p.name.replace("Кирпич ", "").replace("Блок ", "");
          return `<span class="${on ? "" : "no"}">${short}</span>`;
        }).join("")}
      </div>
      <div class="contacts">
        ${best
          ? `<div class="mailrow"><a href="mailto:${best.e}">${best.e}</a></div>
             ${rest ? `<span class="more">и ещё ${rest} ${plural(rest, "адрес", "адреса", "адресов")}</span>` : ""}`
          : `<span class="more">Контакты не найдены</span>`}
      </div>
    </div>
  </article>`;
}

function plural(n, one, few, many) {
  const m10 = n % 10, m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return one;
  if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return few;
  return many;
}

function render() {
  const list = visible();
  const ok = list.filter(isVerified);
  const maybe = list.filter(s => !isVerified(s));

  $("cntOk").textContent = ok.length;
  $("cntMaybe").textContent = maybe.length;
  $("headOk").textContent = ok.length ? `${ok.length}` : "";
  $("headMaybe").textContent = maybe.length ? `${maybe.length}` : "";

  $("cardsOk").innerHTML = ok.length
    ? ok.map(cardHtml).join("")
    : `<div class="empty"><strong>Подтверждённые поставщики не найдены</strong>
         <p>Ниже — возможные поставщики, их контакты нужно проверить вручную.</p></div>`;

  $("cardsMaybe").innerHTML = maybe.length
    ? maybe.map(cardHtml).join("")
    : `<div class="empty"><strong>Возможных поставщиков нет</strong>
         <p>По текущим фильтрам ничего не осталось.</p></div>`;

  const n = state.picked.size;
  $("selN").textContent = `Выбрано ${n}`;
  $("exportBtn").disabled = n === 0;
  $("selAll").textContent = n && n >= list.length ? "Снять выбор" : "Выбрать все";
}

function toast(text, undo, stop) {
  const el = document.createElement("div");
  el.className = "toast" + (stop ? " stop" : "");
  el.innerHTML = `<span>${text}</span>`;
  if (undo) {
    const b = document.createElement("button");
    b.className = "btn"; b.textContent = "Вернуть";
    b.onclick = () => { undo(); el.remove(); render(); };
    el.appendChild(b);
  }
  $("toasts").appendChild(el);
  setTimeout(() => el.remove(), 7000);
}

document.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-act]");
  if (!btn) return;
  const card = e.target.closest(".card");
  if (!card) return;
  const host = card.dataset.host;
  const s = DATA.suppliers.find(x => x.host === host);
  const act = btn.dataset.act;

  if (act === "pick") {
    state.picked.has(host) ? state.picked.delete(host) : state.picked.add(host);
    render();
  } else if (act === "open") {
    window.open("https://" + host, "_blank", "noopener");
  } else if (act === "black" || act === "irrelevant") {
    state.removed.set(host, act);
    state.picked.delete(host);
    toast(
      act === "black"
        ? `<b>${host}</b> добавлен в чёрный список компании — больше не появится ни в одной заявке.`
        : `<b>${host}</b> помечен нерелевантным для этой заявки.`,
      () => state.removed.delete(host),
      true
    );
    render();
  }
});

$("fRegion").onchange = (e) => { state.region = e.target.value; render(); };
$("fKind").onchange   = (e) => { state.kind = e.target.value; render(); };
$("fSearch").oninput  = (e) => { state.q = e.target.value.trim(); render(); };

$("selAll").onclick = () => {
  const list = visible();
  if (state.picked.size >= list.length) state.picked.clear();
  else list.forEach(s => state.picked.add(s.host));
  render();
};

$("exportBtn").onclick = () => {
  const rows = DATA.suppliers.filter(s => state.picked.has(s.host));
  $("sheetNote").textContent =
    `${rows.length} ${plural(rows.length, "компания", "компании", "компаний")} · ` +
    `файл Excel со всеми найденными адресами. В прототипе показано содержимое выгрузки.`;
  $("sheetTable").innerHTML =
    `<thead><tr><th>Компания</th><th>Сайт</th><th>Регион</th><th>ИНН</th><th>Email</th><th>Закрывает</th></tr></thead>
     <tbody>${rows.map(s => `<tr>
       <td>${cleanTitle(s)}</td>
       <td class="mono">${s.host}</td>
       <td>${s.region || "—"}</td>
       <td class="mono">${s.inn || "—"}</td>
       <td class="mono">${s.emails.map(m => m.e).join("<br>") || "—"}</td>
       <td>${s.covers.map(id => posName[id].replace("Кирпич ", "").replace("Блок ", "")).join(", ") || "—"}</td>
     </tr>`).join("")}</tbody>`;
  $("sheet").classList.add("on");
};
$("sheetClose").onclick = () => $("sheet").classList.remove("on");
$("sheet").onclick = (e) => { if (e.target === $("sheet")) $("sheet").classList.remove("on"); };
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") $("sheet").classList.remove("on");
});

/* Демонстрация фонового поиска — утверждённое требование: пользователь видит
   ход работы, но глубиной не управляет. Кнопок «найти ещё» здесь нет. */
let demo = false, timer = null;
$("demoToggle").onclick = () => {
  demo = !demo;
  $("progress").classList.toggle("on", demo);
  $("demoToggle").textContent = demo ? "Показать результат" : "Показать ход поиска";
  $("statePill").innerHTML = demo
    ? '<span class="dot"></span> Поиск идёт'
    : '<span class="dot"></span> Поиск завершён';
  $("statePill").style.background = demo ? "var(--accent-bg)" : "var(--ok-bg)";
  $("statePill").style.color = demo ? "var(--accent)" : "var(--ok)";
  clearInterval(timer);
  if (demo) {
    let done = 1;
    const total = DATA.positions.length;
    const tick = () => {
      $("progressN").textContent = `Обработано ${done} из ${total} позиций`;
      $("ptrackFill").style.width = (done / total * 100) + "%";
      done = done >= total ? 1 : done + 1;
    };
    tick();
    timer = setInterval(tick, 1800);
  }
};

renderPositions();
renderFilters();
render();
